<?php
namespace App\Http\Controllers;
use App\Models\{ActivityLog,Attendance,Department,Employee,Payroll,Position,User};
use Illuminate\Http\JsonResponse;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\Hash;
class ApiController extends Controller { private function log(Request $r,string $text):void { ActivityLog::create(['user_id'=>$r->user()->user_id,'activity'=>$text,'timestamp'=>now()]); } public function clock(Request $r,string $action):JsonResponse { $employee=$r->user()->employee; abort_unless($employee,403); return DB::transaction(function()use($employee,$action,$r){ $row=Attendance::where('employee_id',$employee->employee_id)->whereDate('attendance_date',today())->lockForUpdate()->first(); if($action==='in'){ if($row){ return response()->json(['message'=>$row->time_out?'You have already completed your attendance for today.':'You are already clocked in.'],422); } $row=Attendance::create(['employee_id'=>$employee->employee_id,'attendance_date'=>today(),'time_in'=>now(),'status'=>'Incomplete']); $this->log($r,'Clocked in'); } else { if(!$row?->time_in||$row->time_out){ return response()->json(['message'=>'No active clock-in found for today.'],422); } $row->update(['time_out'=>now(),'total_hours'=>round($row->time_in->diffInSeconds(now())/3600,2),'status'=>'Completed']); $this->log($r,'Clocked out'); } return response()->json(['attendance'=>$row->fresh(),'message'=>'Attendance updated.']); }); } public function verify(Request $r,Attendance $attendance):JsonResponse { abort_unless($attendance->status==='Completed',422,'Only completed attendance can be verified.'); $attendance->update(['status'=>'Verified']); $this->log($r,'Verified attendance record #'.$attendance->attendance_id); return response()->json(['attendance'=>$attendance]); } public function payroll(Request $r):JsonResponse { $data=$r->validate(['employee_id'=>['required','integer','exists:employees,employee_id'],'period_start'=>['required','date'],'period_end'=>['required','date','after_or_equal:period_start'],'bonuses'=>['nullable','numeric','min:0'],'deductions'=>['nullable','numeric','min:0']]); $employee=Employee::findOrFail($data['employee_id']); $hours=(float)Attendance::where('employee_id',$employee->employee_id)->where('status','Verified')->whereBetween('attendance_date',[$data['period_start'],$data['period_end']])->sum('total_hours'); if($hours<=0){return response()->json(['message'=>'This employee has no verified attendance hours for the selected period.'],422);} $gross=round($hours*(float)$employee->basic_hourly_rate,2); $payroll=Payroll::updateOrCreate(['employee_id'=>$employee->employee_id,'payroll_period_start'=>$data['period_start'],'payroll_period_end'=>$data['period_end']],['verified_hours'=>$hours,'hourly_rate'=>$employee->basic_hourly_rate,'gross_salary'=>$gross,'bonuses'=>$data['bonuses']??0,'deductions'=>$data['deductions']??0,'net_salary'=>$gross+($data['bonuses']??0)-($data['deductions']??0),'processed_by'=>$r->user()->user_id,'processed_date'=>now()]); $this->log($r,'Processed payroll for employee #'.$employee->employee_id); return response()->json(['payroll'=>$payroll]); } }
